arguments.new_string:
        self.vals = ()
    return

def __repr__(self):
    cn = self.__class__.__name__
    # Build repr with all the relevant attributes
    parts = [repr(self.spec)]
    if self.types:
        parts.append('type=%r' % list(self.types))
    if self.instance_of:
        parts.append('instance_of=%r' % list(self.instance_of))
    if self.vals:
        parts.append('vals=%r' % list(self.vals))
    if self.validators:
        parts.append('validators=%r' % list(self.validators))
    if self.default is not RAISE:
        parts.append('default=%r' % self.default)
    return '%s(%s)' % (cn, ', '.join(parts))

